const input = $json || {};

const sampleContext = {
  version: '1.0',
  generatedAt: new Date().toISOString(),
  timezone: 'Asia/Dubai',
  request: {
    text: 'Bu hafta sonu sosyal etkinlik bul'
  },
  userContext: {
    identity: {
      name: 'Savaş',
      language: 'Turkish'
    },
    locations: {
      home: 'Palm Jumeirah, Dubai',
      work: 'Abu Dhabi'
    },
    goals: {
      social: 'Build a quality international social circle',
      dating: 'Create genuine dating opportunities',
      travel: 'Take more weekend trips'
    }
  },
  calendarContext: {
    today: [],
    tomorrow: [],
    thisWeek: []
  },
  derivedContext: {
    isWeekend: true,
    calendarLoad: 'low',
    needsMoreSocial: true,
    needsMoreFitness: true,
    preferredPlanningWindow: {
      start: '17:00',
      end: '23:00'
    }
  },
  userState: {
    energyLevel: 'high',
    mood: 'social',
    budgetAED: 1200,
    maxTravelMinutes: 45
  }
};

const sampleDecision = {
  route: 'social_discovery',
  agentWorkflowName: 'Concierge OS - Social Discovery Agent',
  actionMode: 'discover_analyze_recommend',
  confidence: 0.94,
  isAmbiguous: false,
  needsDiscovery: true,
  requiresApproval: false,
  requiredContext: [
    'memory',
    'calendar',
    'derived_context'
  ],
  reason: 'Social activity is below the weekly target.'
};

return [{
  json: {
    request: input.request || {
      text: 'Bu hafta sonu sosyal etkinlik bul',
      channel: 'manual_test',
      userId: 'savas',
      conversationId: 'manual-test',
      receivedAt: new Date().toISOString()
    },
    context:
      Object.keys(input.context || {}).length
        ? input.context
        : sampleContext,
    decision:
      Object.keys(input.decision || {}).length
        ? input.decision
        : sampleDecision,
    sourceEvents:
      Array.isArray(input.sourceEvents)
        ? input.sourceEvents
        : [],
    connectorOutputs:
      Array.isArray(input.connectorOutputs)
        ? input.connectorOutputs
        : [],
    forwardedItems:
      Array.isArray(input.forwardedItems)
        ? input.forwardedItems
        : [],
    metadata: {
      correlationId:
        input.metadata?.correlationId ||
        `agent-orchestrator-${Date.now()}`,
      sourceWorkflow:
        input.metadata?.sourceWorkflow ||
        'Concierge OS - Agent Orchestrator',
      testMode:
        input.metadata?.testMode ?? true,
      ...input.metadata
    }
  }
}];

const input = $json || {};
const decision = input.decision || {};
const route = String(
  decision.route || 'general_concierge'
).trim();

const supportedRoutes = [
  'social_discovery'
];

return [{
  json: {
    ...input,
    selectedRoute: route,
    isSocialDiscovery:
      route === 'social_discovery',
    isImplemented:
      supportedRoutes.includes(route),
    targetWorkflow:
      route === 'social_discovery'
        ? 'Concierge OS - Social Discovery Agent'
        : decision.agentWorkflowName ||
          'Concierge OS - General Concierge'
  }
}];

const input = $json || {};

return [{
  json: {
    request: input.request,
    context: input.context,
    events: input.sourceEvents || [],
    sourceEvents: input.sourceEvents || [],
    connectorOutputs: input.connectorOutputs || [],
    forwardedItems: input.forwardedItems || [],
    metadata: {
      ...input.metadata,
      sourceWorkflow:
        'Concierge OS - Agent Orchestrator',
      selectedRoute:
        input.selectedRoute,
      targetWorkflow:
        input.targetWorkflow
    }
  }
}];

const input = $json || {};

return [{
  json: {
    success: true,
    result: {
      selectedAgent:
        input.selectedRoute ||
        'general_concierge',
      selectedRoute:
        input.selectedRoute ||
        'general_concierge',
      targetWorkflow:
        input.targetWorkflow || null,
      executionStatus:
        'agent_not_implemented',
      agentResponse: {
        success: true,
        result: {
          agent:
            input.selectedRoute ||
            'general_concierge',
          summary:
            `The route '${input.selectedRoute}' was selected, but its specialist workflow has not been implemented yet.`,
          recommendations: []
        }
      },
      recommendations: []
    },
    memoryUpdates: [],
    approvalRequests: [],
    logs: [{
      timestamp:
        new Date().toISOString(),
      workflow:
        'Concierge OS - Agent Orchestrator',
      level: 'warning',
      correlationId:
        input.metadata?.correlationId || '',
      message:
        'Selected agent is not implemented.',
      details: {
        route:
          input.selectedRoute,
        targetWorkflow:
          input.targetWorkflow
      }
    }],
    nextAction: {
      type:
        'implement_or_connect_agent',
      targetWorkflow:
        input.targetWorkflow || null
    },
    error: null
  }
}];
